import React, { useState, useEffect } from 'react';
import { Sprinter } from '@chainsafe/sprinter-sdk';
import { Card, CardContent, Button, Select, MenuItem, TextField, Typography, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper } from '@mui/material';

const SprinterWidget = () => {
  const [account, setAccount] = useState('');
  const [balances, setBalances] = useState({
    USDT: {},
    USDC: {}
  });
  const [selectedAmount, setSelectedAmount] = useState('');
  const [selectedDestination, setSelectedDestination] = useState('');
  const [selectedToken, setSelectedToken] = useState('USDT');
  const [quote, setQuote] = useState(null);
  const [destinationAddress, setDestinationAddress] = useState('');

  const sprinter = new Sprinter();

  const supportedChains = [
    { id: 43114, name: 'Avalanche' },
    { id: 1, name: 'Mainnet' },
    { id: 10, name: 'Optimism' },
    { id: 137, name: 'Polygon' },
    { id: 8453, name: 'Base' },
    { id: 42161, name: 'Arbitrum' },
    { id: 100, name: 'Gnosis' },
  ];

  useEffect(() => {
    setAccount('0x1234...5678');
    fetchBalances();
  }, []);

  const fetchBalances = async () => {
    try {
      const usdcBalances = await sprinter.getUserBalances(account, ['USDC']);
      const usdtBalances = await sprinter.getUserBalances(account, ['USDT']);

      const newBalances = {
        USDC: {},
        USDT: {}
      };

      supportedChains.forEach(chain => {
        newBalances.USDC[chain.id] = usdcBalances.USDC.find(b => b.chainId === chain.id)?.balance || '0';
        newBalances.USDT[chain.id] = usdtBalances.USDT.find(b => b.chainId === chain.id)?.balance || '0';
      });

      setBalances(newBalances);
    } catch (error) {
      console.error('Error fetching balances:', error);
    }
  };

  const handlePayClick = async () => {
    try {
      const solution = await sprinter.getSolution({
        account,
        token: selectedToken,
        destinationChain: parseInt(selectedDestination),
        amount: selectedAmount
      });
      setQuote(solution[0]);
    } catch (error) {
      console.error('Error getting quote:', error);
    }
  };

  const handleAggregateClick = async () => {
    try {
      console.log('Executing transaction with quote:', quote);
      setQuote(null);
      setSelectedAmount('');
      setSelectedDestination('');
      setDestinationAddress('');
    } catch (error) {
      console.error('Error executing transaction:', error);
    }
  };

  const renderBalanceTable = () => (
    <TableContainer component={Paper}>
      <Table>
        <TableHead>
          <TableRow>
            <TableCell>Network</TableCell>
            <TableCell>USDT</TableCell>
            <TableCell>USDC</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {supportedChains.map((chain) => (
            <TableRow key={chain.id}>
              <TableCell>{chain.name}</TableCell>
              <TableCell>{balances.USDT[chain.id]}</TableCell>
              <TableCell>{balances.USDC[chain.id]}</TableCell>
            </TableRow>
          ))}
          <TableRow>
            <TableCell><strong>TOTAL</strong></TableCell>
            <TableCell><strong>{Object.values(balances.USDT).reduce((a, b) => a + Number(b), 0)}</strong></TableCell>
            <TableCell><strong>{Object.values(balances.USDC).reduce((a, b) => a + Number(b), 0)}</strong></TableCell>
          </TableRow>
        </TableBody>
      </Table>
    </TableContainer>
  );

  return (
    <Card>
      <CardContent>
        <Typography variant="h5" gutterBottom>Sprinter Balance Aggregator</Typography>
        {renderBalanceTable()}
        <TextField
          type="number"
          value={selectedAmount}
          onChange={(e) => setSelectedAmount(e.target.value)}
          placeholder="Amount"
          fullWidth
          margin="normal"
        />
        <Select
          value={selectedDestination}
          onChange={(e) => setSelectedDestination(e.target.value)}
          fullWidth
          margin="normal"
        >
          <MenuItem value="">Select destination chain</MenuItem>
          {supportedChains.map((chain) => (
            <MenuItem key={chain.id} value={chain.id}>{chain.name}</MenuItem>
          ))}
        </Select>
        <Select
          value={selectedToken}
          onChange={(e) => setSelectedToken(e.target.value)}
          fullWidth
          margin="normal"
        >
          <MenuItem value="USDT">USDT</MenuItem>
          <MenuItem value="USDC">USDC</MenuItem>
        </Select>
        <Button onClick={handlePayClick} variant="contained" color="primary" fullWidth>
          Quote Aggregate
        </Button>
      </CardContent>
      {quote && (
        <CardContent>
          <Typography variant="h6">Quote</Typography>
          <Typography>Total: {quote.amount} {selectedToken}</Typography>
          <Typography>Destination: {supportedChains.find(c => c.id === quote.destinationChain)?.name}</Typography>
          <Typography>Fee: {quote.fee.amount}</Typography>
          <Typography>Gas Cost: {quote.gasCost.amount}</Typography>
          <TextField
            type="text"
            value={destinationAddress}
            onChange={(e) => setDestinationAddress(e.target.value)}
            placeholder="Destination Address"
            fullWidth
            margin="normal"
          />
          <Button onClick={handleAggregateClick} variant="contained" color="primary" fullWidth>
            Pay/Aggregate
          </Button>
        </CardContent>
      )}
    </Card>
  );
};

export default SprinterWidget;
